            counts.add(snapshot.path("resultFeedback"));
        }
        return counts;
    }

    private static final class FeedbackCounts {
        int accurate;
        int inaccurate;
        int unknown;
        int unassessed;

        void add(JsonNode feedback) {
            String assessment = feedback == null || feedback.isNull()
                    ? null : feedback.path("assessment").asText(null);
            if ("ACCURATE".equals(assessment)) {
                accurate++;
            } else if ("INACCURATE".equals(assessment)) {
                inaccurate++;
            } else if ("UNKNOWN".equals(assessment)) {
                unknown++;
            } else {
                unassessed++;
            }
        }
    }

    private Map<String, Integer> issueCounts(List<String> resultIds) {
        if (resultIds.isEmpty()) {
            return Map.of();
        }
        List<AgentIssue> rows = db.mapper(AgentIssueMapper.class).selectList(
                new LambdaQueryWrapper<AgentIssue>()
                        .select(AgentIssue::getResultId)
                        .in(AgentIssue::getResultId, resultIds));
        Map<String, Integer> counts = new LinkedHashMap<>();
        for (AgentIssue row : rows) {
            counts.merge(row.getResultId(), 1, Integer::sum);
        }
        return counts;
    }

