    private FeedbackView feedback(AgentFeedback row) {
        return row == null ? null : new FeedbackView(row.getAssessment(), row.getComment(),
                row.getRevision() == null ? 0 : row.getRevision(), row.getUpdatedAt());
    }

    private JsonNode feedbackNode(FeedbackView feedback) {
        ObjectNode node = mapper.createObjectNode();
        node.put("assessment", feedback.assessment());
        node.put("comment", feedback.comment());
        node.put("revision", feedback.revision());
        node.put("updatedAt", feedback.updatedAt() == null ? null : feedback.updatedAt().toString());
        return node;
    }

    private JsonNode bodyNode(AgentReviewResult result) {
        String body = result.getBody();
        if (body == null || body.isBlank()) {
            throw new ApiException(ErrorCode.INTERNAL_ERROR, "保存的结果正文缺失，不能冻结");
        }
        if ("AGENT".equals(result.getKind())) {
            return mapper.getNodeFactory().textNode(body);
        }
        return requiredJson(body, true, "专项结果正文");
    }

    private JsonNode requiredJson(String value, boolean object, String label) {
        JsonNode node = readJsonOrNull(value);
        if (node == null || (object ? !node.isObject() : !node.isArray())) {
            throw new ApiException(ErrorCode.INTERNAL_ERROR, "保存的" + label + "损坏，不能冻结");
        }
        return node;
    }

    private ArrayNode frozenMaterials(JsonNode provenance) {
        ArrayNode snapshots = mapper.createArrayNode();
        JsonNode references = provenance.path("materials");
        if (references.isMissingNode()) return snapshots;
        if (!references.isArray()) {
            throw new ApiException(ErrorCode.INTERNAL_ERROR, "保存的材料引用损坏，不能冻结");
        }
        Set<String> seen = new LinkedHashSet<>();
        for (JsonNode reference : references) {
            String id = reference.path("id").asText("");
            if (id.isBlank()) {
                throw new ApiException(ErrorCode.INTERNAL_ERROR, "保存的材料引用缺少 ID，不能冻结");
            }
            if (!seen.add(id)) continue;
            AgentMaterial material = db.mapper(AgentMaterialMapper.class).selectById(id);
            if (material == null) {
                throw new ApiException(ErrorCode.CONFLICT, "来源代码材料缺失，不能冻结", Map.of("materialId", id));
            }
            // 从当时已保存的片段复制证据，不向仓库重新读取，也不把元数据引用当成代码快照。
            ObjectNode node = snapshots.addObject();
            node.put("id", material.getId());
            node.put("projectId", material.getProjectId());
            node.put("sha", material.getSha());
            node.put("path", material.getPath());
            node.put("side", material.getSide());
            node.put("startLine", material.getStartLine());
            node.put("endLine", material.getEndLine());
            node.put("content", material.getContent());
            node.put("contentHash", material.getContentHash());
            node.put("completeness", material.getCompleteness());
            node.put("diagnostic", material.getDiagnostic());
        }
        return snapshots;
    }

    private JsonNode readSnapshot(String snapshot) {
        JsonNode node = readJsonOrNull(snapshot);
        if (node == null || !node.isObject()) {
            throw new ApiException(ErrorCode.INTERNAL_ERROR, "保存的报告来源数据损坏，无法读取");
        }
        return node;
    }

    private JsonNode readJsonOrNull(String value) {
        if (value == null || value.isBlank()) {
            return null;
        }
        try {
            return mapper.readTree(value);
        } catch (JsonProcessingException ignored) {
            return null;
        }
    }

    private String json(JsonNode node) {
        try {
            return mapper.writeValueAsString(node);
        } catch (JsonProcessingException e) {
            throw new ApiException(ErrorCode.INTERNAL_ERROR, "报告冻结数据无法序列化");
        }
    }

    private TaskSource source(AgentReviewTask task) {
        JsonNode input = readJsonOrNull(task.getInputSnapshot());
        JsonNode source = input == null ? null : input.path("source");
        return new TaskSource(source == null || source.isMissingNode() ? "FILES" : source.path("kind").asText("FILES"),
                textOrNull(source, "branch"), textOrNull(source, "commitSha"), textOrNull(source, "baseSha"));
    }

    private static String textOrNull(JsonNode node, String field) {
        if (node == null) {
            return null;
        }
        JsonNode value = node.get(field);
        return value == null || value.isNull() ? null : value.asText();
    }

    private static String requireKind(String kind) {
        String normalized = kind.trim().toUpperCase();
        if (!KINDS.contains(normalized)) {
            throw new ApiException(ErrorCode.VALIDATION_FAILED,
                    "结果类型只能是 ISSUE、PATTERN、COUPLING 或 AGENT");
        }
        return normalized;
    }

    private static <T> Map<String, T> byId(List<String> ids,
                                           Function<List<String>, List<T>> load, Function<T, String> id) {
        if (ids.isEmpty()) {
            return Map.of();
        }
        return load.apply(ids).stream().collect(Collectors.toMap(id, Function.identity(), (a, b) -> b));
    }

    private record TaskSource(String kind, String branch, String commitSha, String baseSha) { }

    private record FeedbackView(String assessment, String comment, int revision, LocalDateTime updatedAt) { }
}

package com.codereview.agent.report;

import com.codereview.agent.api.ApiException;
import com.codereview.agent.api.ErrorCode;
import com.codereview.agent.dto.ReportDtos;
import com.codereview.agent.entity.AgentReportSource;
import com.codereview.agent.prompt.PromptFact;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.JsonNodeFactory;
import org.springframework.stereotype.Service;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.stream.Collectors;

/**
 * 把冻结来源整理成模型可读的事实与指标。
 *
 * <p>这里只读取 P32.3 保存的 {@code report_source.source_snapshot}，不联查最新结果、反馈、
 * 材料或仓库。结构化结果保留问题、模式、耦合事实及人工反馈；证据正文只取来源引用指向的
 * 已保存片段，不额外读取当前分支。事实文本进入统一组装后再由公共调用做容量判断，
 * 超限直接失败，不在这里截断。
 */
@Service
public class ReportFactsBuilder {

    static final String FACTS_VERSION = "1";

    private final ObjectMapper mapper;

    public ReportFactsBuilder(ObjectMapper mapper) {
        this.mapper = mapper;
    }

    public ReportFacts build(List<AgentReportSource> sources) {
        if (sources == null || sources.isEmpty()) {
            throw new ApiException(ErrorCode.REPORT_INPUT_INVALID, "报告没有冻结来源，不能生成正文");
        }
        List<SourceFact> parsed = new ArrayList<>();
        for (AgentReportSource source : sources) {
            parsed.add(parse(source));
        }

        Map<String, Integer> kinds = new LinkedHashMap<>();
        Set<String> taskIds = new LinkedHashSet<>();
        Set<String> versionKeys = new LinkedHashSet<>();
        List<ReportDtos.SourceSummary> summaries = new ArrayList<>();
        int issueTotal = 0;
        FeedbackCounts issueCounts = new FeedbackCounts();
        FeedbackCounts resultCounts = new FeedbackCounts();
        for (SourceFact fact : parsed) {
            kinds.merge(fact.kind(), 1, Integer::sum);
            taskIds.add(fact.taskId());
            versionKeys.add(fact.versionKey());
            summaries.add(fact.summary());
            issueTotal += fact.issueCount();
            issueCounts.add(fact.issueFeedback());
            resultCounts.add(fact.resultFeedback());
        }

        List<PromptFact> facts = new ArrayList<>();
        facts.add(new PromptFact("SUMMARY", summaryText(parsed, kinds, taskIds.size(),
                versionKeys.size(), issueTotal, issueCounts, resultCounts)));
        for (SourceFact fact : parsed) {
            facts.add(new PromptFact("S" + fact.summary().ordinal(), fact.text()));
        }
        List<String> missing = parsed.stream().flatMap(fact -> fact.missing().stream()).toList();
        return new ReportFacts(facts, missing, parsed.size(), taskIds.size(), versionKeys.size(),
                kinds, summaries);
    }

    private String summaryText(List<SourceFact> sources, Map<String, Integer> kinds, int taskCount,
                               int versionCount, int issueTotal, FeedbackCounts issueCounts,
                               FeedbackCounts resultCounts) {
        StringBuilder text = new StringBuilder();
        text.append("来源 ").append(sources.size()).append(" 个；任务 ").append(taskCount)
                .append(" 个；仓库版本 ").append(versionCount).append(" 个；问题 ")
                .append(issueTotal).append(" 个。\n");
        text.append("类型：").append(kinds.entrySet().stream()
                .map(entry -> kindName(entry.getKey()) + " " + entry.getValue())
                .collect(Collectors.joining("、"))).append("。\n");
        text.append("问题级人工反馈：").append(issueCounts.describe()).append("。\n");
        text.append("结果级人工反馈：").append(resultCounts.describe()).append("。\n");
        text.append("仓库版本分组：\n");
        Map<String, List<Integer>> groups = new LinkedHashMap<>();
        for (SourceFact source : sources) {
            groups.computeIfAbsent(source.versionKey(), ignored -> new ArrayList<>())
                    .add(source.summary().ordinal());
        }
        for (Map.Entry<String, List<Integer>> entry : groups.entrySet()) {
            String label = sources.stream().filter(source -> source.versionKey().equals(entry.getKey()))
                    .findFirst().orElseThrow().groupLabel();
            text.append("- ").append(label).append("：")
                    .append(entry.getValue().stream().map(ordinal -> "S" + ordinal)
                            .collect(Collectors.joining("、"))).append('\n');
        }
        return text.toString();
    }

    private SourceFact parse(AgentReportSource row) {
        JsonNode snapshot = readObject(row.getSourceSnapshot(), "报告来源");
        String resultId = text(snapshot, "resultId");
        String taskId = text(snapshot, "taskId");
        String kind = text(snapshot, "kind");
        if (blank(resultId) || blank(taskId) || blank(kind)) {
            throw invalid("报告来源缺少结果、任务或类型标识");
        }
        JsonNode project = object(snapshot, "project");
        JsonNode task = object(snapshot, "task");
        JsonNode target = object(snapshot, "target");
        JsonNode result = object(snapshot, "result");
        JsonNode body = result.path("body");
        JsonNode provenance = result.path("provenance");
        if (body.isMissingNode() || body.isNull()) {
            throw invalid("报告来源缺少结果正文");
        }
        Map<String, JsonNode> materials = materials(snapshot);
        List<String> missing = new ArrayList<>();
        List<String> evidence = new ArrayList<>();
        Set<String> evidenceKeys = new LinkedHashSet<>();

        String projectId = text(project, "id");
        String projectName = text(project, "name");
        String repoUrl = text(project, "repoUrl");
        String branch = text(task, "branch");
        String commitSha = text(task, "commitSha");
        String baseSha = text(task, "baseSha");
        String headSha = text(target, "headSha");
        if (blank(headSha)) {
            headSha = commitSha;
        }
        String path = text(target, "path");
        String oldPath = text(target, "oldPath");
        String versionKey = projectId + "|" + nullToEmpty(headSha) + "|" + nullToEmpty(baseSha);
        String groupLabel = (blank(projectName) ? nullToUnknown(projectId) : projectName)
                + "（" + projectId + "）@" + nullToUnknown(headSha)
                + (blank(baseSha) ? "" : "（父 " + baseSha + "）");

        String summary = summaryOf(kind, body);
        List<JsonNode> issues = array(snapshot.path("issues"));
        List<JsonNode> bodyIssues = array(body.path("issues"));
        List<JsonNode> patterns = array(body.path("patterns"));
        List<JsonNode> observations = array(body.path("observations"));
        List<String> limitations = new ArrayList<>(strings(body.path("limitations")));
        JsonNode couplingFacts = provenance.path("couplingFacts");
        if (couplingFacts.isObject()) {
            limitations.addAll(strings(couplingFacts.path("limitations")));
        }

        FeedbackCounts issueFeedback = new FeedbackCounts();
        FeedbackCounts resultFeedback = new FeedbackCounts();
        for (JsonNode gap : array(provenance.path("materialGaps"))) {
            missing.add(nullToEmpty(text(gap, "code")) + "：" + nullToEmpty(text(gap, "subject"))
                    + " " + nullToEmpty(text(gap, "detail")));
        }
        if ("ISSUE".equals(kind)) {
            for (JsonNode issue : issues) {
                issueFeedback.add(feedbackCount(issue.path("feedback")));
                collectEvidence(issue.path("locations"), materials, evidenceKeys, evidence, missing);
            }
            for (JsonNode issue : bodyIssues) {
                collectEvidence(issue.path("evidence"), materials, evidenceKeys, evidence, missing);
            }
        } else {
            resultFeedback = feedbackCount(snapshot.path("resultFeedback"));
            for (JsonNode pattern : patterns) {
                collectEvidence(pattern.path("evidence"), materials, evidenceKeys, evidence, missing);
            }
            for (JsonNode observation : observations) {
                collectEvidence(observation.path("evidence"), materials, evidenceKeys, evidence, missing);
            }
        }

        FeedbackCounts sourceFeedback = "ISSUE".equals(kind) ? issueFeedback : resultFeedback;
        ReportDtos.SourceSummary sourceSummary = new ReportDtos.SourceSummary(
                row.getOrdinal(), resultId, kind, projectId, projectName, taskId, text(task, "route"),
                path, headSha, baseSha, displaySummary(summary), issues.size(),
                sourceFeedback.accurate, sourceFeedback.inaccurate, sourceFeedback.unknown,
                sourceFeedback.unassessed);
        String facts = sourceText(projectName, repoUrl, task, path, oldPath, branch, commitSha,
                baseSha, headSha, summary, issues, patterns, observations, limitations, couplingFacts,
                resultFeedback, evidence, missing);
        if (!"ISSUE".equals(kind)) {
            facts += "当时结果级评价与评论：" + feedbackText(snapshot.path("resultFeedback")) + "\n";
        }
        for (int index = 0; index < bodyIssues.size(); index++) {
            String relation = text(bodyIssues.get(index), "changeRelation");
            if (!blank(relation)) facts += "问题 " + (index + 1) + " 变更关系：" + relation + "\n";
        }
        return new SourceFact(kind, taskId, versionKey, groupLabel, sourceSummary, issueFeedback,
                resultFeedback, issues.size(), facts, missing);
    }

    private String sourceText(String projectName, String repoUrl, JsonNode task, String path,
                              String oldPath, String branch, String commitSha, String baseSha,
                              String headSha, String summary, List<JsonNode> issues,
                              List<JsonNode> patterns, List<JsonNode> observations,
                              List<String> limitations, JsonNode couplingFacts,
                              FeedbackCounts resultFeedback, List<String> evidence,
                              List<String> missing) {
        StringBuilder text = new StringBuilder();
        text.append("项目：").append(nullToUnknown(projectName)).append("｜仓库：")
                .append(nullToUnknown(repoUrl)).append("｜版本：").append(nullToUnknown(headSha));
        if (!blank(baseSha)) {
            text.append("（父 ").append(baseSha).append("）");
        }
        text.append('\n');
        text.append("任务：").append(text(task, "id")).append("｜状态：").append(text(task, "state"))
                .append("｜来源：").append(text(task, "sourceKind"));
        if (!blank(branch)) {
            text.append("｜分支：").append(branch);
        }
        if (!blank(commitSha)) {
            text.append("｜提交：").append(commitSha);
        }
        text.append('\n');
        text.append("文件：").append(nullToUnknown(path));
        if (!blank(oldPath)) {
            text.append("（旧路径：").append(oldPath).append("）");
        }
        text.append('\n');
        text.append("结论：").append(nullToEmpty(summary)).append('\n');
        if (!issues.isEmpty()) {
            text.append("问题 ").append(issues.size()).append(" 个：\n");
            for (JsonNode issue : issues) {
                text.append("  - ").append(text(issue, "ordinal")).append(". [")
                        .append(text(issue, "severity")).append('/').append(text(issue, "category"))
                        .append("] ").append(text(issue, "title")).append("（")
                        .append(locations(issue.path("locations"))).append("）\n");
                text.append("    原因：").append(nullToEmpty(text(issue, "reason"))).append('\n');
                text.append("    建议：").append(nullToEmpty(text(issue, "suggestion"))).append('\n');
                text.append("    反馈：").append(feedbackText(issue.path("feedback"))).append('\n');
            }
        }
        if (!patterns.isEmpty()) {
            text.append("模式候选 ").append(patterns.size()).append(" 个：\n");
            for (JsonNode pattern : patterns) {
                text.append("  - ").append(nullToEmpty(text(pattern, "name"))).append("（")
                        .append(nullToEmpty(text(pattern, "family"))).append("，角色：")
                        .append(nullToEmpty(text(pattern, "role"))).append("）：")
                        .append(nullToEmpty(text(pattern, "explanation"))).append('\n');
            }
        }
        if (!observations.isEmpty()) {
            text.append("耦合观察 ").append(observations.size()).append(" 个：\n");
            for (JsonNode observation : observations) {
                text.append("  - ").append(nullToEmpty(text(observation, "title"))).append("：")
                        .append(nullToEmpty(text(observation, "explanation")));
                List<String> dependencyIds = strings(observation.path("dependencyIds"));
                if (!dependencyIds.isEmpty()) {
                    text.append("；依赖：").append(String.join("、", dependencyIds));
                }
                text.append('\n');
                if (!blank(text(observation, "suggestion"))) {
                    text.append("    建议：").append(text(observation, "suggestion")).append('\n');
                }
            }
        }
        if (couplingFacts.isObject()) {
            text.append("耦合指标：已解析出向依赖 ")
                    .append(couplingFacts.path("resolvedOutgoingCount").asInt())
                    .append(" 个，未解析类型 ").append(couplingFacts.path("unresolvedTypeCount").asInt())
                    .append(" 个，覆盖 ").append(couplingFacts.path("coverage").asText("UNKNOWN"))
                    .append("。\n");
            for (JsonNode edge : array(couplingFacts.path("edges"))) {
                text.append("  - ").append(text(edge, "id")).append(" ").append(text(edge, "sourceType"))
                        .append(" -> ").append(text(edge, "targetType")).append("（")
                        .append(text(edge, "relation")).append("，").append(text(edge, "targetPath"))
                        .append(':').append(text(edge, "line")).append("）\n");
            }
        }
        if (!limitations.isEmpty()) {
            text.append("限制：\n");
            for (String limitation : limitations) {
                text.append("  - ").append(limitation).append('\n');
            }
        }
        text.append("结果级反馈：").append(resultFeedback.describe()).append('\n');
        if (!evidence.isEmpty()) {
            text.append("已保存代码证据：\n");
            for (String item : evidence) {
                text.append(item).append('\n');
            }
        }
        if (!missing.isEmpty()) {
            text.append("材料缺口：\n");
            for (String item : missing) {
                text.append("  - ").append(item).append('\n');
            }
        }
        return text.toString();
    }

    private void collectEvidence(JsonNode locations, Map<String, JsonNode> materials,
                                 Set<String> keys, List<String> evidence, List<String> missing) {
        for (JsonNode location : array(locations)) {
            String materialId = text(location, "materialId");
            JsonNode material = blank(materialId) ? null : materials.get(materialId);
            if (material == null) {
                missing.add("材料 " + nullToUnknown(materialId) + " 行 "
                        + location.path("startLine").asInt() + "-" + location.path("endLine").asInt()
                        + " 未关联保存材料，代码原文需在冻结来源中查看");
                continue;
            }
            int start = location.path("startLine").asInt(material.path("startLine").asInt(1));
            int end = location.path("endLine").asInt(start);
            String key = text(material, "id") + ":" + start + "-" + end;
            if (!keys.add(key)) {
                continue;
            }
            String excerpt = lines(material, start, end);
            if (excerpt == null) {
                missing.add("材料 " + text(material, "path") + " 在 " + start + "-" + end
                        + " 行没有保存正文");
                continue;
            }
            evidence.add("  - " + text(material, "path") + " 行 " + start + "-" + end
                    + "（材料 " + text(material, "id") + "，" + text(material, "side")
                    + "，SHA " + text(material, "sha")
                    + "）：\n" + excerpt);
        }
    }

    private String lines(JsonNode material, int start, int end) {
        String content = text(material, "content");
        if (content == null || content.isEmpty()) {
            return null;
        }
        int materialStart = material.path("startLine").asInt(1);
        String[] lines = content.split("\n", -1);
        int from = start - materialStart;
        int to = end - materialStart;
        if (from < 0 || to < from || to >= lines.length
                || end > material.path("endLine").asInt(materialStart + lines.length - 1)) {
            return null;
        }
        StringBuilder text = new StringBuilder();
        for (int index = from; index <= to; index++) {
            text.append("    ").append(String.format("%6d | %s", materialStart + index, lines[index]))
                    .append('\n');
        }
        return text.toString();
    }

    private Map<String, JsonNode> materials(JsonNode snapshot) {
        Map<String, JsonNode> result = new LinkedHashMap<>();
        for (JsonNode material : array(snapshot.path("materials"))) {
            String id = text(material, "id");
            if (!blank(id)) {
                result.put(id, material);
            }
        }
        return result;
    }

    private String locations(JsonNode locations) {
        if (!locations.isArray() || locations.isEmpty()) {
            return "位置未保存";
        }
        List<String> parts = new ArrayList<>();
        for (JsonNode location : locations) {
            parts.add(text(location, "path") + ":" + location.path("startLine").asInt()
                    + "-" + location.path("endLine").asInt());
        }
        return String.join("、", parts);
    }

    private String feedbackText(JsonNode feedback) {
        if (feedback == null || feedback.isNull() || feedback.isMissingNode()) {
            return "未反馈";
        }
        String assessment = text(feedback, "assessment");
        String comment = text(feedback, "comment");
        return (blank(assessment) ? "未判定" : assessment) + (blank(comment) ? "" : "（" + comment + "）");
    }

    private FeedbackCounts feedbackCount(JsonNode feedback) {
        FeedbackCounts count = new FeedbackCounts();
        String assessment = feedback == null || feedback.isNull() ? null : text(feedback, "assessment");
        if ("ACCURATE".equals(assessment)) {
            count.accurate++;
        } else if ("INACCURATE".equals(assessment)) {
            count.inaccurate++;
        } else if ("UNKNOWN".equals(assessment)) {
            count.unknown++;
        } else {
            count.unassessed++;
        }
        return count;
    }

    private String summaryOf(String kind, JsonNode body) {
        if ("AGENT".equals(kind)) {
            return body.isTextual() ? body.asText() : "";
        }

        }
        return text(body, "summary");
    }

    private String displaySummary(String summary) {
        String value = summary == null ? "" : summary.strip();
        int lineBreak = value.indexOf('\n');
        if (lineBreak >= 0) {
            value = value.substring(0, lineBreak);
        }
        return value.length() <= 200 ? value : value.substring(0, 200) + "…";
    }

    private JsonNode readObject(String value, String label) {
        if (blank(value)) {
            throw invalid(label + "为空");
        }
        try {
            JsonNode node = mapper.readTree(value);
            if (!node.isObject()) {
                throw invalid(label + "不是对象");
            }
            return node;
        } catch (ApiException e) {
            throw e;
        } catch (Exception e) {
            throw invalid(label + "不是合法 JSON");
        }
    }

    private static JsonNode object(JsonNode node, String field) {
        JsonNode value = node.path(field);
        return value.isObject() ? value : JsonNodeFactory.instance.objectNode();
    }

    private static List<JsonNode> array(JsonNode node) {
        if (!node.isArray()) {
            return List.of();
        }
        List<JsonNode> values = new ArrayList<>();
        node.forEach(values::add);
        return values;
    }

    private static List<String> strings(JsonNode node) {
        if (!node.isArray()) {
            return List.of();
        }
        List<String> values = new ArrayList<>();
        node.forEach(value -> {
            if (value.isTextual() && !value.asText().isBlank()) {
                values.add(value.asText());
            }
        });
        return values;
    }

    private static String text(JsonNode node, String field) {
        JsonNode value = node == null ? null : node.get(field);
        return value == null || value.isNull() ? null : value.asText();
    }

    private static String nullToEmpty(String value) {
        return value == null ? "" : value;
    }

    private static String nullToUnknown(String value) {
        return blank(value) ? "UNKNOWN" : value;
    }

    private static String shortSha(String sha) {
        return blank(sha) ? "UNKNOWN" : sha.length() <= 12 ? sha : sha.substring(0, 12);
    }

    private static boolean blank(String value) {
        return value == null || value.isBlank();
    }

    private static ApiException invalid(String message) {
        return new ApiException(ErrorCode.REPORT_INPUT_INVALID, message);
    }

    private static String kindName(String kind) {
        return switch (kind) {
            case "ISSUE" -> "问题审查";
            case "PATTERN" -> "设计模式";
            case "COUPLING" -> "耦合度";
            case "AGENT" -> "Agent";
            default -> kind;
        };
    }

    /** 组装后的事实包；来源摘要用于详情页，不回写数据库。 */
    public record ReportFacts(List<PromptFact> facts, List<String> missingNotes, int sourceCount,
                              int taskCount, int versionCount, Map<String, Integer> kindCounts,
                              List<ReportDtos.SourceSummary> summaries) {
    }

    private record SourceFact(String kind, String taskId, String versionKey, String groupLabel,
                              ReportDtos.SourceSummary summary, FeedbackCounts issueFeedback,
                              FeedbackCounts resultFeedback, int issueCount, String text,
                              List<String> missing) {
    }

    private static final class FeedbackCounts {
        int accurate;
        int inaccurate;
        int unknown;
        int unassessed;

        void add(FeedbackCounts other) {
            accurate += other.accurate;
            inaccurate += other.inaccurate;
            unknown += other.unknown;
            unassessed += other.unassessed;
        }

        String describe() {
            return "准确 " + accurate + " / 不准确 " + inaccurate + " / 无法判断 " + unknown
                    + " / 未反馈 " + unassessed;
        }
    }
}

package com.codereview.agent.report;

import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;
import com.baomidou.mybatisplus.core.conditions.update.LambdaUpdateWrapper;
import com.codereview.agent.api.ApiException;
import com.codereview.agent.api.ErrorCode;
import com.codereview.agent.db.AgentDatabase;
import com.codereview.agent.dto.ReportDtos;
import com.codereview.agent.entity.AgentModelConfig;
import com.codereview.agent.entity.AgentReport;
import com.codereview.agent.entity.AgentReportSource;
import com.codereview.agent.invocation.InvocationRequest;
import com.codereview.agent.invocation.InvocationResult;
import com.codereview.agent.invocation.InvocationScope;
import com.codereview.agent.invocation.ModelInvocationService;
import com.codereview.agent.invocation.ModelSnapshot;
import com.codereview.agent.mapper.AgentModelConfigMapper;
import com.codereview.agent.mapper.AgentReportMapper;
import com.codereview.agent.mapper.AgentReportSourceMapper;
import com.codereview.agent.prompt.AssembledPrompt;
import com.codereview.agent.prompt.PromptAssemblyService;
import com.codereview.agent.prompt.PromptInput;
import com.codereview.agent.prompt.PromptPurpose;
import com.codereview.agent.support.AgentTime;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.stereotype.Service;

import java.time.LocalDateTime;
import java.util.List;
import java.util.Map;

import static com.codereview.agent.report.ReportStates.QUEUED;
import static com.codereview.agent.report.ReportStates.RUNNING;
import static com.codereview.agent.report.ReportStates.SUCCEEDED;

/**
 * 报告生成的后台执行器。
 *
 * <p>先条件更新为 RUNNING，再读取冻结来源、整理事实、经统一组装与公共调用生成正文。
 * 成功要求 Markdown 正文至少引用一个存在的冻结来源；失败只写入错误，不写正文，
 * 冻结来源和输入摘要保持不变。报告调用与专项调用共用容量、并发和调用记录。
 */
@Service
@ConditionalOnProperty(prefix = "agent.datasource", name = "url")
public class ReportExecutionWorker {

    private static final Logger log = LoggerFactory.getLogger(ReportExecutionWorker.class);

    private final AgentDatabase db;
    private final ObjectMapper mapper;
    private final ReportFactsBuilder factsBuilder;
    private final PromptAssemblyService assembly;
    private final ModelInvocationService invocation;
    private final ReportGenerationProperties properties;

    public ReportExecutionWorker(AgentDatabase db, ObjectMapper mapper,
                                 ReportFactsBuilder factsBuilder, PromptAssemblyService assembly,
                                 ModelInvocationService invocation,
                                 ReportGenerationProperties properties) {
        this.db = db;
        this.mapper = mapper;
        this.factsBuilder = factsBuilder;
        this.assembly = assembly;
        this.invocation = invocation;
        this.properties = properties;
    }

    public void execute(String reportId) {
        AgentReport report = db.mapper(AgentReportMapper.class).selectById(reportId);
        if (report == null || !QUEUED.equals(report.getState())) {
            return;
        }
        if (!markRunning(report)) {
            return;
        }
        LocalDateTime deadline = AgentTime.now()
                .plusMinutes(Math.max(1, properties.getGenerationTimeoutMinutes()));
        try {
            List<AgentReportSource> sources = db.mapper(AgentReportSourceMapper.class).selectList(
                    new LambdaQueryWrapper<AgentReportSource>()
                            .eq(AgentReportSource::getReportId, reportId)
                            .orderByAsc(AgentReportSource::getOrdinal));
            ReportFactsBuilder.ReportFacts facts = factsBuilder.build(sources);
            ModelSnapshot model = model(report);
            AssembledPrompt prompt = assembly.assemble(new PromptInput(PromptPurpose.REPORT, "1",
                    null, null, null, null, null, null, null, List.of(), List.of(),
                    facts.missingNotes(), facts.facts(), null, report.getTitle(),
                    instruction(report)));
            InvocationResult result = invocation.invoke(new InvocationRequest(model, prompt,
                    InvocationScope.standalone(deadline), false, reportId,
                    properties.getOutputTokens()));
            String body = result.content();
            if (body != null && body.length() > Math.max(1, properties.getMaxBodyChars())) {
                throw new ApiException(ErrorCode.MODEL_OUTPUT_INVALID,
                        "报告正文超过保存上限 " + properties.getMaxBodyChars() + " 字符",
                        Map.of("length", body.length()));
            }
            ReportCitationValidator.validate(body, facts.sourceCount());
            if (!AgentTime.now().isBefore(deadline)) {
                throw new ApiException(ErrorCode.UPSTREAM_TIMEOUT, "报告生成超过总期限，迟到正文未发布");
            }
            finishSuccess(reportId, body);
        } catch (ApiException e) {
            log.warn("报告 {} 生成失败：{} {}", reportId, e.errorCode().code(), e.getMessage());
            finishFailure(reportId, e.errorCode().code(), e.getMessage());
        } catch (RuntimeException e) {
            log.error("报告 {} 生成异常", reportId, e);
            finishFailure(reportId, ErrorCode.INTERNAL_ERROR.code(), "报告生成异常");
        }
    }

    private boolean markRunning(AgentReport report) {
        int changed = db.mapper(AgentReportMapper.class).update(null,
                new LambdaUpdateWrapper<AgentReport>()
                        .eq(AgentReport::getId, report.getId())
                        .eq(AgentReport::getState, QUEUED)
                        .eq(AgentReport::getRevision, report.getRevision())
                        .set(AgentReport::getState, RUNNING)
                        .set(AgentReport::getStartedAt, AgentTime.now())
                        .set(AgentReport::getUpdatedAt, AgentTime.now())
                        .setSql("revision = revision + 1"));
        return changed > 0;
    }

    private void finishSuccess(String reportId, String body) {
        int changed = db.mapper(AgentReportMapper.class).update(null,
                new LambdaUpdateWrapper<AgentReport>()
                        .eq(AgentReport::getId, reportId)
                        .eq(AgentReport::getState, RUNNING)
                        .set(AgentReport::getState, SUCCEEDED)
                        .set(AgentReport::getBody, body)
                        .set(AgentReport::getErrorCode, null)
                        .set(AgentReport::getErrorMessage, null)
                        .set(AgentReport::getFinishedAt, AgentTime.now())
                        .set(AgentReport::getUpdatedAt, AgentTime.now())
                        .setSql("revision = revision + 1"));
        if (changed == 0) {
            log.info("报告 {} 的成功结果未写入：报告已被其他操作结束", reportId);
        }
    }

    private void finishFailure(String reportId, String code, String message) {
        int changed = db.mapper(AgentReportMapper.class).update(null,
                new LambdaUpdateWrapper<AgentReport>()
                        .eq(AgentReport::getId, reportId)
                        .eq(AgentReport::getState, RUNNING)
                        .set(AgentReport::getState, ReportStates.FAILED)
                        .set(AgentReport::getBody, null)
                        .set(AgentReport::getErrorCode, truncate(code, 40))
                        .set(AgentReport::getErrorMessage, truncate(message, 1000))
                        .set(AgentReport::getFinishedAt, AgentTime.now())
                        .set(AgentReport::getUpdatedAt, AgentTime.now())
                        .setSql("revision = revision + 1"));
        if (changed == 0) {
            log.info("报告 {} 的失败结果未写入：报告已被其他操作结束", reportId);
        }
    }

    private ModelSnapshot model(AgentReport report) {
        JsonNode snapshot = readObject(report.getModelSnapshot());
        if (snapshot == null) {
            throw new ApiException(ErrorCode.REPORT_INPUT_INVALID, "报告缺少模型快照，不能生成");
        }
        String modelId = text(snapshot, "id");
        AgentModelConfig current = modelId == null ? null
                : db.mapper(AgentModelConfigMapper.class).selectById(modelId);
        if (current == null) {
            throw new ApiException(ErrorCode.CONFIG_INCOMPLETE, "生成模型已被删除，不能继续生成报告",
                    Map.of("modelId", modelId == null ? "" : modelId));
        }
        return new ModelSnapshot(modelId, text(snapshot, "name"), text(snapshot, "baseUrl"),
                text(snapshot, "modelName"), current.getCredential(), intOrNull(snapshot, "contextWindow"),
                intOrNull(snapshot, "maxOutput"), text(snapshot, "tokenizer"),
                text(snapshot, "protocol"), intOrNull(snapshot, "revision"));
    }

    private String instruction(AgentReport report) {
        JsonNode snapshot = readObject(report.getInstructionSnapshot());
        return snapshot == null ? null : text(snapshot, "text");
    }

    private JsonNode readObject(String value) {
        if (value == null || value.isBlank()) {
            return null;
        }
        try {
            JsonNode node = mapper.readTree(value);
            return node != null && node.isObject() ? node : null;
        } catch (Exception e) {
            return null;
        }
    }

    private static Integer intOrNull(JsonNode node, String field) {
        JsonNode value = node.get(field);
        return value == null || value.isNull() ? null : value.asInt();
    }

    private static String text(JsonNode node, String field) {
        JsonNode value = node == null ? null : node.get(field);
        return value == null || value.isNull() ? null : value.asText();
    }

    private static String truncate(String value, int max) {
        if (value == null) {
            return null;
        }
        return value.length() <= max ? value : value.substring(0, max);
    }
}

package com.codereview.agent.service;

import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;
import com.baomidou.mybatisplus.core.conditions.update.LambdaUpdateWrapper;
import com.codereview.agent.api.ApiException;
import com.codereview.agent.api.ErrorCode;
import com.codereview.agent.db.AgentDatabase;
import com.codereview.agent.dto.FeedbackDtos;
import com.codereview.agent.entity.AgentFeedback;
import com.codereview.agent.entity.AgentIssue;
import com.codereview.agent.entity.AgentReviewResult;
import com.codereview.agent.mapper.AgentFeedbackMapper;
import com.codereview.agent.mapper.AgentIssueMapper;
import com.codereview.agent.mapper.AgentReviewResultMapper;
import com.codereview.agent.support.AgentIds;
import com.codereview.agent.support.AgentTime;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.stereotype.Service;

import java.util.Map;
import java.time.LocalDateTime;

/** 稳定问题或完整专项结果上的人工反馈。 */
@Service
@ConditionalOnProperty(prefix = "agent.datasource", name = "url")
public class FeedbackService {
    private final AgentDatabase db;

    public FeedbackService(AgentDatabase db) {
        this.db = db;
    }

    public FeedbackDtos.View get(String subjectKind, String subjectId) {
        Subject subject = requireSubject(subjectKind, subjectId);
        AgentFeedback row = find(subject.kind(), subject.id());
        return view(subject, row);
    }

    public FeedbackDtos.View save(String subjectKind, String subjectId, FeedbackDtos.Update request) {
        Subject subject = requireSubject(subjectKind, subjectId);
        if (request.expectedRevision() == null) {
            throw new ApiException(ErrorCode.VALIDATION_FAILED, "expectedRevision 为必填项");
        }
        AgentFeedbackMapper mapper = db.mapper(AgentFeedbackMapper.class);
        AgentFeedback current = find(subject.kind(), subject.id());
        int expected = request.expectedRevision();
        if (current == null) {
            if (expected != 0) throw conflict(subject, null);
            AgentFeedback row = new AgentFeedback();
            row.setId(AgentIds.next());
            row.setSubjectKind(subject.kind());
            row.setSubjectId(subject.id());
            row.setAssessment(blankToNull(request.assessment()));
            row.setComment(request.comment());
            row.setRevision(1);
            row.setCreatedAt(AgentTime.now());
            row.setUpdatedAt(AgentTime.now());
            try {
                mapper.insert(row);
                return view(subject, row);
            } catch (DuplicateKeyException race) {
                throw conflict(subject, find(subject.kind(), subject.id()));
            }
        }
        if (current.getRevision() != expected) throw conflict(subject, current);
        LocalDateTime savedAt = AgentTime.now();
        String assessment = blankToNull(request.assessment());
        int changed = mapper.update(null, new LambdaUpdateWrapper<AgentFeedback>()
                .eq(AgentFeedback::getSubjectKind, subject.kind())
                .eq(AgentFeedback::getSubjectId, subject.id())
                .eq(AgentFeedback::getRevision, expected)
                .set(AgentFeedback::getAssessment, assessment)
                .set(AgentFeedback::getComment, request.comment())
                .set(AgentFeedback::getRevision, expected + 1)
                .set(AgentFeedback::getUpdatedAt, savedAt));
        if (changed == 0) throw conflict(subject, find(subject.kind(), subject.id()));
        // 返回本次条件更新确认写入的值；再次查询可能读到另一页面随后保存的更高 revision。
        return new FeedbackDtos.View(subject.kind(), subject.id(), assessment,
                request.comment(), expected + 1, savedAt);
    }

    private Subject requireSubject(String kind, String id) {
        String validId;
        try {
            validId = AgentIds.requireValid(id, "反馈主体 ID");
        } catch (IllegalArgumentException invalid) {
            throw new ApiException(ErrorCode.VALIDATION_FAILED, "反馈主体 ID 不合法");
        }
        if ("ISSUE".equals(kind)) {
            AgentIssue issue = db.mapper(AgentIssueMapper.class).selectById(validId);
            if (issue == null) throw new ApiException(ErrorCode.NOT_FOUND, "问题不存在");
            AgentReviewResult result = db.mapper(AgentReviewResultMapper.class).selectById(issue.getResultId());
            if (result == null || !"ISSUE".equals(result.getKind()) || !"COMPLETE".equals(result.getCompleteness())) {
                throw new ApiException(ErrorCode.CONFLICT, "仅完整的问题审查结果允许反馈");
            }
            return new Subject("ISSUE", validId);
        }
        if ("RESULT".equals(kind)) {
            AgentReviewResult result = db.mapper(AgentReviewResultMapper.class).selectById(validId);
            if (result == null) throw new ApiException(ErrorCode.NOT_FOUND, "审查结果不存在");
            if (!"COMPLETE".equals(result.getCompleteness())
                    || !("PATTERN".equals(result.getKind()) || "COUPLING".equals(result.getKind()))) {
                throw new ApiException(ErrorCode.CONFLICT, "仅完整的模式或耦合结果允许结果级反馈");
            }
            return new Subject("RESULT", validId);
        }
        throw new ApiException(ErrorCode.VALIDATION_FAILED, "主体类型只能是 ISSUE 或 RESULT");
    }

    private AgentFeedback find(String kind, String id) {
        return db.mapper(AgentFeedbackMapper.class).selectOne(new LambdaQueryWrapper<AgentFeedback>()
                .eq(AgentFeedback::getSubjectKind, kind).eq(AgentFeedback::getSubjectId, id));
    }

    private FeedbackDtos.View view(Subject subject, AgentFeedback row) {
        return row == null
                ? new FeedbackDtos.View(subject.kind(), subject.id(), null, null, 0, null)
                : new FeedbackDtos.View(subject.kind(), subject.id(), row.getAssessment(), row.getComment(),
                        row.getRevision(), row.getUpdatedAt());
    }

    private ApiException conflict(Subject subject, AgentFeedback current) {
        return new ApiException(ErrorCode.REVISION_CONFLICT, "反馈已被其他页面修改；读取最新内容并手动合并后再保存",
                Map.of("current", view(subject, current)));
    }

    private static String blankToNull(String value) {
        return value == null || value.isBlank() ? null : value;
    }

    private record Subject(String kind, String id) { }
}

package com.codereview.agent.api;

import com.codereview.agent.dto.ReportDtos;
import com.codereview.agent.report.ReportGenerationService;
import com.codereview.agent.service.ReportInputService;
import jakarta.validation.Valid;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.http.ContentDisposition;
import org.springframework.http.HttpHeaders;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

import java.net.URI;
import java.nio.charset.StandardCharsets;
import java.util.List;

/**
 * 报告 v2 入口。
 *
 * <p>候选与冻结是报告生成的前置步骤：候选只返回完整结果，冻结创建一条
 * {@code INPUT_FROZEN} 报告并保存来源快照；正文生成由独立入口选择模型后异步执行。
 * 下载只返回已成功保存的正文，失败报告没有可下载的成功内容。
 */
@RestController
@RequestMapping("/api/v2/reports")
@ConditionalOnProperty(prefix = "agent.datasource", name = "url")
public class ReportV2Controller {

    private final ReportInputService inputService;
    private final ReportGenerationService generationService;

    public ReportV2Controller(ReportInputService inputService,
                              ReportGenerationService generationService) {
        this.inputService = inputService;
        this.generationService = generationService;
    }

    @GetMapping("/candidates")
    public PageResponse<ReportDtos.Candidate> candidates(
            @RequestParam(required = false) String projectId,
            @RequestParam(required = false) String taskId,
            @RequestParam(required = false) String kind,
            @RequestParam(required = false) String cursor,
            @RequestParam(required = false) Integer limit) {
        return inputService.candidates(projectId, taskId, kind, cursor, limit);
    }

    @PostMapping("/inputs")
    public ResponseEntity<ReportDtos.FrozenInput> freeze(
            @Valid @RequestBody ReportDtos.FreezeRequest request) {
        ReportDtos.FrozenInput frozen = inputService.freeze(request);
        return ResponseEntity.created(URI.create("/api/v2/reports/" + frozen.reportId() + "/inputs"))
                .body(frozen);
    }

    @GetMapping("/{id}/inputs")
    public ReportDtos.FrozenInput inputs(@PathVariable String id) {
        return inputService.frozenInput(id);
    }

    @GetMapping
    public PageResponse<ReportDtos.ReportSummary> list(
            @RequestParam(required = false) String cursor,
            @RequestParam(required = false) Integer limit) {
        return generationService.list(cursor, limit);
    }

    /** 受理后返回 202；HTTP 成功只表示进入生成队列，正文状态须继续读取报告。 */
    @PostMapping("/{id}/generate")
    public ResponseEntity<ReportDtos.ReportDetail> generate(
            @PathVariable String id, @Valid @RequestBody ReportDtos.GenerateRequest request) {
        ReportDtos.ReportDetail detail = generationService.start(id, request);
        return ResponseEntity.accepted().body(detail);
    }

    @GetMapping("/{id}")
    public ReportDtos.ReportDetail detail(@PathVariable String id) {
        return generationService.detail(id);
    }

    @GetMapping("/{id}/sources/{ordinal}")
    public ReportDtos.FrozenSource source(@PathVariable String id, @PathVariable int ordinal) {
        return generationService.source(id, ordinal);
    }

    @GetMapping("/{id}/calls")
    public List<ReportDtos.CallSummary> calls(@PathVariable String id) {
        return generationService.calls(id);
    }

    @GetMapping("/{id}/download")
    public ResponseEntity<byte[]> download(@PathVariable String id) {
        ReportGenerationService.Download download = generationService.download(id);
        ContentDisposition disposition = ContentDisposition.attachment()
                .filename(download.fileName(), StandardCharsets.UTF_8).build();
        return ResponseEntity.ok()
                .header(HttpHeaders.CONTENT_DISPOSITION, disposition.toString())
                .contentType(MediaType.parseMediaType("text/markdown; charset=UTF-8"))
                .body(download.content());
    }
}

    private SqlSessionFactory newFactory() {
        MybatisConfiguration configuration = new MybatisConfiguration();
        configuration.setEnvironment(new Environment(
                "agent", new SpringManagedTransactionFactory(), pool));
        configuration.setMapUnderscoreToCamelCase(true);
        GlobalConfig global = new GlobalConfig();
        global.setBanner(false);
        global.setDbConfig(new GlobalConfig.DbConfig()
                .setLogicDeleteField("isDeleted")
                .setLogicDeleteValue("1")
                .setLogicNotDeleteValue("0"));
        GlobalConfigUtils.setGlobalConfig(configuration, global);
        for (Class<?> mapper : mappers) {
            configuration.addMapper(mapper);
        }
        return new MybatisSqlSessionFactoryBuilder().build(configuration);
    }

    /** 取 MyBatis 映射器；每次调用都通过当前线程的会话取代理，不做跨请求缓存。 */
    public <T> T mapper(Class<T> mapperType) {
        return template.getMapper(mapperType);
    }

    /** 在新库事务内执行；抛异常整体回滚。 */
    public <T> T inTransaction(Supplier<T> work) {
        return transactionTemplate.execute(status -> work.get());
    }

    /** 只读健康检查用：库名与版本标记。 */
    public String schemaVersion() {
        guard.postMigrate(pool);
        return AgentSchemaGuard.EXPECTED_VERSION;
    }

    @Override
    public void destroy() {
        if (pool != null) {
            pool.close();
        }
    }
}

package com.codereview.agent.report;

import com.codereview.agent.api.ApiException;
import com.codereview.agent.api.ErrorCode;

import java.util.LinkedHashSet;
import java.util.Map;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * 报告引用校验。
 *
 * <p>只接受统一组装协议约定的 {@code [S1]} 形式；引用序号必须落在冻结来源范围内。
 * 至少要求一处引用，避免正文看似完整却没有可追溯来源。这里不判断结论真伪，
 * 也不允许把未知来源自动改写成最近来源。
 */
public final class ReportCitationValidator {

    private static final Pattern CITATION = Pattern.compile("\\[S(\\d+)]");

    private ReportCitationValidator() {
    }

    public static int validate(String body, int sourceCount) {
        if (body == null || body.isBlank()) {
            throw new ApiException(ErrorCode.MODEL_OUTPUT_INVALID, "模型没有返回报告正文");
        }
        Matcher matcher = CITATION.matcher(body);
        Set<Integer> cited = new LinkedHashSet<>();
        while (matcher.find()) {
            int ordinal;
            try {
                ordinal = Integer.parseInt(matcher.group(1));
            } catch (NumberFormatException e) {
                throw invalid(matcher.group(), sourceCount);
            }
            if (ordinal < 1 || ordinal > sourceCount) {
                throw invalid(matcher.group(), sourceCount);
            }
            cited.add(ordinal);
        }
        if (cited.isEmpty()) {
            throw new ApiException(ErrorCode.REPORT_CITATION_INVALID,
                    "报告正文没有引用任何冻结来源，不能作为完成报告", Map.of("sourceCount", sourceCount));
        }
        return cited.size();
    }

    private static ApiException invalid(String citation, int sourceCount) {
        return new ApiException(ErrorCode.REPORT_CITATION_INVALID,
                "报告引用了不存在的冻结来源 " + citation + "（共 " + sourceCount + " 个来源）",
                Map.of("citation", citation, "sourceCount", sourceCount));
    }
}

public AgentDatabase(AgentDataSourceProperties props, List<Class<?>> mappers) {
    this.props = props;
    this.mappers = mappers;
    start();
}

private void start() {
    if (props.getUrl() == null || props.getUrl().isBlank()) {
        throw new AgentSchemaMismatchException("未配置 agent.datasource.url，无法初始化新库");
    }
    this.guard = new AgentSchemaGuard(props.getExpectedDatabase(), props.getHistoryTable());
    this.pool = newPool();
    guard.preMigrate(pool);
    Flyway flyway = Flyway.configure()
            .dataSource(pool)
            .locations(props.getMigrationLocation())
            .table(props.getHistoryTable())
            .baselineOnMigrate(false)
            .validateMigrationNaming(true)
            .load();
    flyway.migrate();
    guard.postMigrate(pool);
    this.template = new SqlSessionTemplate(newFactory());
    this.transactionTemplate = new TransactionTemplate(new DataSourceTransactionManager(pool));
}

private HikariDataSource newPool() {
    HikariConfig config = new HikariConfig();
    config.setPoolName("agent-db");
    config.setJdbcUrl(props.getUrl());
    config.setUsername(props.getUsername());
    config.setPassword(props.getPassword());
    if (props.getDriverClassName() != null && !props.getDriverClassName().isBlank()) {
        config.setDriverClassName(props.getDriverClassName());
    }
    config.setMaximumPoolSize(props.getMaximumPoolSize());
    config.setMinimumIdle(1);
    config.setConnectionTimeout(10_000);
    return new HikariDataSource(config);
}
